<script>
import avatar from "@/assets/avatar.jpg";

export default {
  name: "VideoCommentView",
  data() {
    return {
      isFoucsArea: false,
      comment: "",
      isChecked: false,
      activeReplyCommentId: null,
      activeReplyTargetName: "",
      isReplyFocus: false,
      replyComment: "",
      commentObserver: null,
      bottomAlerted: false,
      commentList: [
        {
          id: 1,
          username: "小小用户",
          content: "这个视频节奏挺好，镜头语言也很舒服。",
          time: "2026-04-10 18:35",
          likeNum: 103,
          images: [avatar, avatar],
          replies: [
            {
              id: 101,
              username: "用户名字",
              content: "同感，后半段转场很丝滑。",
              time: "2026-04-10 18:40",
              likeNum: 23,
            },
          ],
        },
        {
          id: 2,
          username: "甜一口没",
          content: "BGM 选得很好，求歌单。",
          time: "2026-04-10 19:12",
          likeNum: 58,
          images: [],
          replies: [
            {
              id: 201,
              username: "托马斯家的",
              content: "同问，蹲一个UP回复。",
              time: "2026-04-10 19:20",
              likeNum: 8,
            },
          ],
        },
        {
          id: 3,
          username: "今晚不加班",
          content: "这期看完直接收藏了，期待下期。",
          time: "2026-04-10 20:05",
          likeNum: 16,
          images: [],
          replies: [],
        },
      ],
    };
  },
  mounted() {
    this.initBottomObserver();
  },
  beforeUnmount() {
    if (this.commentObserver) {
      this.commentObserver.disconnect();
      this.commentObserver = null;
    }
  },
  methods: {
    onFocusArea() {
      this.isFoucsArea = true;
    },
    onBlurArea() {
      this.isFoucsArea = false;
    },
    openReplyBox(commentId, targetName) {
      this.activeReplyCommentId = commentId;
      this.activeReplyTargetName = targetName;
      this.replyComment = "";
      this.isReplyFocus = true;

      this.$nextTick(() => {
        const refKey = `replyTextarea-${commentId}`;
        const ref = this.$refs[refKey];
        const textarea = Array.isArray(ref) ? ref[0] : ref;
        if (textarea) {
          textarea.focus();
        }
      });
    },
    onFocusReply() {
      this.isReplyFocus = true;
    },
    onBlurReply() {
      this.isReplyFocus = false;
    },
    submitReply(commentId) {
      const value = this.replyComment.trim();
      if (!value) return;

      const comment = this.commentList.find((item) => item.id === commentId);
      if (!comment) return;

      comment.replies.push({
        id: Date.now(),
        username: "我",
        content: value,
        time: "刚刚",
        likeNum: 0,
      });

      this.replyComment = "";
      this.isReplyFocus = false;
      this.activeReplyCommentId = null;
      this.activeReplyTargetName = "";
    },
    initBottomObserver() {
      const target = this.$refs.commentBottomSentinel;
      if (!target) return;

      this.commentObserver = new IntersectionObserver(
        ([entry]) => {
          if (entry.isIntersecting) {
            if (!this.bottomAlerted) {
              this.bottomAlerted = true;
              window.alert("评论区到底部了（后端接口还没接）");
            }
          } else {
            this.bottomAlerted = false;
          }
        },
        {
          root: null,
          threshold: 0.1,
        }
      );

      this.commentObserver.observe(target);
    },
  },
};
</script>

